/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename in the order it would be applied (lexicographic / numeric order).
 *
 * Before processing migrations, the script resolves DATABASE_URL from a .env
 * file and logs a redacted connection summary to confirm the target database.
 *
 * Usage:
 *   node migrate.js                        # dry-run against .env.test (default)
 *   node migrate.js --apply                # apply mode  against .env.test (default)
 *   node migrate.js --env .env.production  # override which .env file to load
 *   node migrate.js --apply --env .env     # combine flags freely
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR  = path.resolve(__dirname, 'migrations');
const DRY_RUN         = !process.argv.includes('--apply');

/** Resolve the env-file path from --env <file>, falling back to .env.test. */
const ENV_FILE = (() => {
  const idx = process.argv.indexOf('--env');
  return path.resolve(__dirname, idx !== -1 && process.argv[idx + 1]
    ? process.argv[idx + 1]
    : '.env.test');
})();

// ─── .env parser ─────────────────────────────────────────────────────────────

/**
 * Minimal .env parser — no external dependencies required.
 *
 * Handles:
 *   - KEY=value
 *   - KEY="quoted value"
 *   - KEY='quoted value'
 *   - Inline # comments
 *   - Leading/trailing whitespace
 *   - Blank lines and lines that start with #
 *
 * Does NOT mutate process.env; returns a plain object instead so the
 * caller decides which values to use.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`.env file not found: ${filePath}`);
  }

  const raw  = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  for (const rawLine of raw.split('\n')) {
    const line = rawLine.trim();

    // Skip blank lines and comments.
    if (!line || line.startsWith('#')) continue;

    // Only process lines that contain an = sign.
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key        = line.slice(0, eqIdx).trim();
    let   valueRaw   = line.slice(eqIdx + 1).trim();

    // Strip inline comments that are not inside quotes.
    // e.g.  KEY=value  # comment  →  value
    const inlineComment = valueRaw.match(/^([^"'][^#]*?)\s+#.*$/);
    if (inlineComment) valueRaw = inlineComment[1].trim();

    // Strip matching surrounding quotes.
    if (
      (valueRaw.startsWith('"') && valueRaw.endsWith('"')) ||
      (valueRaw.startsWith("'") && valueRaw.endsWith("'"))
    ) {
      valueRaw = valueRaw.slice(1, -1);
    }

    if (key) vars[key] = valueRaw;
  }

  return vars;
}

// ─── Connection-string helpers ────────────────────────────────────────────────

/**
 * Parses a postgres:// connection string into its structural components.
 * Uses the built-in URL class so no third-party parser is needed.
 *
 * @param {string} connectionString - Full DATABASE_URL value.
 * @returns {{ protocol: string, host: string, port: string, database: string }}
 * @throws {Error} If the string cannot be parsed as a URL.
 */
function parseConnectionString(connectionString) {
  let parsed;
  try {
    parsed = new URL(connectionString);
  } catch {
    throw new Error('DATABASE_URL is not a valid URL.');
  }

  return {
    protocol : parsed.protocol.replace(':', ''),   // "postgres"
    host     : parsed.hostname,                     // "db.internal"
    port     : parsed.port || '5432',              // "5432"
    database : parsed.pathname.replace(/^\//, ''), // "production"
  };
}

/**
 * Builds a human-readable, REDACTED connection summary.
 * Credentials (username and password) are never included in the output.
 *
 * @param {string} connectionString - Full DATABASE_URL value.
 * @returns {string} e.g. "postgres://db.internal:5432/production"
 */
function redactedConnectionSummary(connectionString) {
  const { protocol, host, port, database } = parseConnectionString(connectionString);
  return `${protocol}://${host}:${port}/${database}`;
}

// ─── Connection resolver ──────────────────────────────────────────────────────

/**
 * Loads DATABASE_URL from the given .env file, validates it, and logs a
 * redacted confirmation message.  No network connection is made.
 *
 * @param {string} envFilePath - Absolute path to the .env file to read.
 * @returns {string} The raw (un-redacted) DATABASE_URL, for internal use only.
 */
function resolveConnection(envFilePath) {
  console.log(`[DB] Reading connection string from : ${path.relative(process.cwd(), envFilePath)}`);

  let envVars;
  try {
    envVars = parseEnvFile(envFilePath);
  } catch (err) {
    throw new Error(`Failed to parse env file — ${err.message}`);
  }

  const connectionString = envVars['DATABASE_URL'];

  if (!connectionString) {
    throw new Error(`DATABASE_URL is not defined in ${path.basename(envFilePath)}.`);
  }

  // Validate by parsing; throws with a clear message on malformed URLs.
  parseConnectionString(connectionString);

  // Only the redacted summary is ever logged — credentials stay hidden.
  console.log(`[DB] Connected (simulated) to      : ${redactedConnectionSummary(connectionString)}`);

  return connectionString; // returned for internal use; never logged again
}

// ─── Migration file helpers ───────────────────────────────────────────────────

/**
 * Returns an array of absolute paths to every *.sql file inside `dir`,
 * sorted lexicographically (so numeric prefixes like 001_, 002_ order
 * migrations correctly).
 *
 * @param {string} dir - Directory to scan.
 * @returns {string[]} Sorted list of absolute file paths.
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort()                                    // lexicographic = numeric order when zero-padded
    .map(name => path.join(dir, name));
}

/**
 * Reads a SQL file and returns its content as a string.
 *
 * @param {string} filePath - Absolute path to a .sql file.
 * @returns {string} File contents.
 */
function readSqlFile(filePath) {
  return fs.readFileSync(filePath, 'utf8');
}

// ─── Core runner ──────────────────────────────────────────────────────────────

/**
 * Main entry-point.
 * 1. Resolves and validates the database connection string.
 * 2. Discovers migration files.
 * 3. Logs each file that would be (or is being) applied.
 */
function runMigrations() {
  console.log('='.repeat(60));
  console.log('  Database Migration Runner');
  console.log('='.repeat(60));
  console.log(`  Migrations dir : ${MIGRATIONS_DIR}`);
  console.log(`  Env file       : ${path.relative(process.cwd(), ENV_FILE)}`);
  console.log(`  Mode           : ${DRY_RUN ? 'dry-run (pass --apply to execute)' : 'APPLY'}`);
  console.log('='.repeat(60));
  console.log();

  // ── Step 1: Resolve database connection ────────────────────────────────────
  try {
    resolveConnection(ENV_FILE);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log();

  // ── Step 2: Discover migration files ───────────────────────────────────────
  let files;
  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('[INFO] No SQL migration files found. Nothing to apply.');
    return;
  }

  console.log(`[INFO] Found ${files.length} migration file(s):\n`);

  // ── Step 3: Process each file ───────────────────────────────────────────────
  files.forEach((filePath, index) => {
    const filename = path.basename(filePath);
    const position = String(index + 1).padStart(2, '0');

    // Read the file to confirm it is readable and non-empty.
    let sql;
    try {
      sql = readSqlFile(filePath);
    } catch (err) {
      console.error(`  [${position}] ✗ UNREADABLE  ${filename}`);
      console.error(`       Reason: ${err.message}`);
      return; // skip this file and continue
    }

    const lineCount = sql.split('\n').length;
    const isEmpty   = sql.trim().length === 0;

    if (isEmpty) {
      console.warn(`  [${position}] ⚠ SKIP (empty) ${filename}`);
      return;
    }

    // ── Log the migration that would be applied ──────────────────────────────
    console.log(`  [${position}] ✔ PENDING     ${filename}  (${lineCount} line(s))`);

    if (DRY_RUN) {
      // In dry-run mode, surface the first non-empty SQL line as a preview.
      const preview = sql.trim().split('\n')[0].trim();
      console.log(`       Preview : ${preview}`);
    } else {
      // --apply: placeholder for real database execution logic.
      // e.g. await db.query(sql);
      console.log(`       [apply]  Execution not yet wired up — add your DB client here.`);
    }
  });

  // ── Summary ─────────────────────────────────────────────────────────────────
  console.log();
  console.log('='.repeat(60));
  console.log(`  ${DRY_RUN ? 'Dry-run complete.' : 'Apply complete.'} ${files.length} file(s) processed.`);
  console.log('='.repeat(60));
}

// ─── Run ──────────────────────────────────────────────────────────────────────

runMigrations();

CREATE TABLE users (
    id      SERIAL PRIMARY KEY,
    name    VARCHAR(100) NOT NULL,
    email   VARCHAR(255) NOT NULL UNIQUE,
    created_at TIMESTAMP DEFAULT NOW()
);

// migrate.js — Database migration runner
// Reads all .sql files from ./migrations/, sorts them in lexicographic order
// (so numeric prefixes like 001_, 002_ … determine the sequence), and logs
// each filename it would apply together with the SQL it contains.

const fs   = require("fs");
const path = require("path");

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, "migrations");
const SQL_EXTENSION  = ".sql";

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every .sql file inside `dir`, sorted in ascending lexicographic
 * order so that numeric prefixes (001_, 002_, …) act as a natural sequence.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of filenames (not full paths).
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter((file) => path.extname(file).toLowerCase() === SQL_EXTENSION)
    .sort(); // lexicographic — relies on numeric prefixes for ordering
}

/**
 * Reads the contents of a single migration file.
 *
 * @param {string} filePath - Absolute path to the .sql file.
 * @returns {string} The raw SQL string.
 */
function readMigration(filePath) {
  return fs.readFileSync(filePath, "utf8").trim();
}

// ─── Core runner ──────────────────────────────────────────────────────────────

/**
 * Discovers, orders, and logs all pending migration files.
 * In a real runner this function would also open a DB connection, track which
 * migrations have already been applied (e.g. via a `schema_migrations` table),
 * execute each SQL inside a transaction, and record the result.
 */
function runMigrations() {
  console.log("=".repeat(60));
  console.log(" Database Migration Runner");
  console.log("=".repeat(60));
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);
  console.log();

  // 1. Discover migration files
  const files = getSqlFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log("No migration files found. Nothing to apply.");
    return;
  }

  console.log(`Found ${files.length} migration file(s):\n`);

  // 2. Process each file in order
  files.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const sql      = readMigration(filePath);
    const step     = String(index + 1).padStart(2, "0");

    console.log(`[${step}] Applying : ${filename}`);
    console.log(`     Path    : ${filePath}`);
    console.log(`     SQL     :\n`);

    // Indent every line of the SQL block for readability
    sql.split("\n").forEach((line) => console.log(`       ${line}`));

    console.log();
    console.log(`     Status  : ✔ Would apply (dry run — no DB connected)`);
    console.log("-".repeat(60));
    console.log();
  });

  // 3. Summary
  console.log(`Migration run complete. ${files.length} file(s) would be applied.`);
  console.log("=".repeat(60));
}

// ─── Entry point ──────────────────────────────────────────────────────────────

runMigrations();

