// Reads all .sql files from ./migrations/, sorts them in lexicographic order
// (so numeric prefixes like 001_, 002_ … determine the sequence), and logs
// each filename it would apply together with the SQL it contains.
//
// Connection string resolution
//   1. Parse DATABASE_URL from .env.test (no third-party dotenv required).
//   2. Validate the value is present and looks like a connection string.
//   3. Log a simulated successful connection before running migrations.

const fs   = require("fs");
const path = require("path");

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, "migrations");
const SQL_EXTENSION  = ".sql";
const ENV_FILE       = path.resolve(__dirname, ".env.test");

// ─── .env parser ──────────────────────────────────────────────────────────────

/**
 * Parses a .env file and returns its contents as a plain key/value object.
 *
 * Handles the most common .env syntax:
 *   - `KEY=value`           plain value
 *   - `KEY="value"`         double-quoted value (quotes are stripped)
 *   - `KEY='value'`         single-quoted value (quotes are stripped)
 *   - `# comment`           full-line comment (ignored)
 *   - inline `# comment`    text after an unquoted `#` is ignored
 *   - blank lines           ignored
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  let raw;

  try {
    raw = fs.readFileSync(filePath, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const result = {};

  for (const line of raw.split("\n")) {
    const trimmed = line.trim();

    // Skip blank lines and full-line comments
    if (!trimmed || trimmed.startsWith("#")) continue;

    // Split only on the first `=` so values that contain `=` are preserved
    const eqIndex = trimmed.indexOf("=");
    if (eqIndex === -1) continue; // no `=` found — not a valid assignment

    const key   = trimmed.slice(0, eqIndex).trim();
    let   value = trimmed.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    } else {
      // Remove any trailing inline comment (e.g. `value # comment`)
      const commentIndex = value.indexOf(" #");
      if (commentIndex !== -1) {
        value = value.slice(0, commentIndex).trim();
      }
    }

    if (key) result[key] = value;
  }

  return result;
}

/**
 * Resolves DATABASE_URL from the .env.test file.
 *
 * Resolution order:
 *   1. The value already present in `process.env` (allows CI overrides).
 *   2. The value found inside ENV_FILE.
 *
