 * the value does not start with a recognised DB protocol so problems are
 * caught early rather than surfacing as a confusing connection error later.
 *
 * Recognised protocols: postgres://, postgresql://, mysql://, sqlite://
 *
 * @returns {string} The validated DATABASE_URL connection string.
 */
function resolveDatabaseUrl() {
  // 1. Prefer an already-set environment variable (e.g. injected by CI)
  if (process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  // 2. Fall back to the .env.test file
  const env = parseEnvFile(ENV_FILE);

  const url = env["DATABASE_URL"];

  if (!url) {
    throw new Error(
      `DATABASE_URL is not defined in ${ENV_FILE}.\n` +
      `Add a line like: DATABASE_URL=postgres://user:pass@host:5432/dbname`
