'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR   = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION    = '.sql';
const DEFAULT_ENV_FILE = path.resolve(__dirname, '.env.test');

// ─── .env parsing ─────────────────────────────────────────────────────────────

/**
 * Minimal .env parser — no third-party dependencies required.
 *
 * Handles the subset of the .env format that matters here:
 *   - `KEY=value` pairs (surrounding whitespace is stripped from the key)
 *   - Lines that start with `#` (after optional whitespace) are skipped
 *   - Blank lines are skipped
 *   - Quoted values (`"…"` or `'…'`) have their outer quotes removed and the
 *     inner content is used verbatim
 *   - Inline `#` comments after an unquoted value are NOT stripped — a
 *     connection string could theoretically contain `#`, so the entire
 *     right-hand side is treated as the value (consistent with dotenv's
 *     behaviour for unquoted values)
 *
 * Returns a plain object of { KEY: 'value' } pairs.
 * Does NOT mutate process.env — the caller decides what to do with the result.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  const raw  = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  for (const rawLine of raw.split('\n')) {
    const line = rawLine.trim();

    // Skip blank lines and full-line comments.
    if (line === '' || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue; // no `=` — not a key-value pair

    const key = line.slice(0, eqIdx).trim();
    if (key === '') continue;

    let value = line.slice(eqIdx + 1); // everything after the first `=`

    // Strip matching outer quotes (single or double).
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    vars[key] = value;
  }

  return vars;
}

