/**
 * Resolves DATABASE_URL using the three-tier priority chain:
 *   1. process.env           (highest — already-set env vars always win)
 *   2. --env-file <path>     (explicit override supplied via CLI flag)
 *   3. .env.test             (lowest — project-level test fallback)
 *
 * Env files are merged in lowest-to-highest order so that higher-priority
 * files overwrite lower-priority ones. process.env is then overlaid on top,
 * ensuring live environment variables can never be shadowed by a file.
 *
 * Files that do not exist are skipped with a warning rather than an error, so
 * the script works correctly when .env.test is absent in production.
 *
 * @returns {string} The resolved DATABASE_URL value.
 * @throws  {Error}  If DATABASE_URL cannot be found in any source.
 */
function resolveDatabaseUrl() {
  // Build the list of env files in ascending priority order (later = wins).
  const envFiles = [DEFAULT_ENV_FILE]; // lowest priority

  // --env-file <path> flag takes precedence over .env.test.
  const envFlagIdx = process.argv.indexOf('--env-file');
  if (envFlagIdx !== -1) {
    const flagValue = process.argv[envFlagIdx + 1];
    if (!flagValue || flagValue.startsWith('--')) {
      throw new Error('--env-file requires a path argument (e.g. --env-file .env.local)');
    }
    envFiles.push(path.resolve(__dirname, flagValue));
  }

