/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in ascending (lexicographic) order.
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./custom_migrations   # optional custom directory
 *
 * The script is intentionally database-agnostic: it performs no live
 * connection, so it is safe to run in any environment for a dry-run preview.
 * Swap the TODO stubs below with your preferred database driver when you are
 * ready to execute the SQL for real.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Resolve the migrations directory from a CLI flag or fall back to default. */
function getMigrationsDir() {
  const flagIndex = process.argv.indexOf('--dir');
  if (flagIndex !== -1 && process.argv[flagIndex + 1]) {
    return path.resolve(process.argv[flagIndex + 1]);
  }
  return path.resolve(__dirname, 'migrations');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Returns an alphabetically-sorted list of .sql filenames found inside
 * `dir`.  Throws a descriptive error when the directory does not exist.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basenames only).
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort(); // lexicographic order — relies on the NNN_ numeric prefix convention

  return sqlFiles;
}

/**
 * Pretty-prints a two-column table to stdout.
 *
 * @param {Array<{order: number, filename: string, fullPath: string}>} migrations
 */
function printPlan(migrations) {
  const colWidth = Math.max(...migrations.map(m => m.filename.length), 'FILE'.length);

  const header = `  #  ${'FILE'.padEnd(colWidth)}  PATH`;
  const divider = '-'.repeat(header.length + 4);

  console.log('\nMigration plan');
  console.log(divider);
  console.log(header);
  console.log(divider);

  for (const { order, filename, fullPath } of migrations) {
    const orderCol  = String(order).padStart(3);
    const fileCol   = filename.padEnd(colWidth);
    console.log(`  ${orderCol}  ${fileCol}  ${fullPath}`);
  }

  console.log(divider);
  console.log(`  ${migrations.length} migration(s) would be applied.\n`);
}

// ---------------------------------------------------------------------------
// Core runner
// ---------------------------------------------------------------------------

/**
 * Discovers migration files and logs the plan.
 * Extend this function with real DB calls when you are ready to execute.
 */
async function run() {
  const migrationsDir = getMigrationsDir();

  console.log(`\nScanning for migrations in: ${migrationsDir}`);

  // 1. Discover files -------------------------------------------------------
  let sqlFiles;
  try {
    sqlFiles = getSqlFiles(migrationsDir);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (sqlFiles.length === 0) {
    console.log('\nNo .sql migration files found — nothing to apply.\n');
    return;
  }

  // 2. Build the ordered plan -----------------------------------------------
  const migrations = sqlFiles.map((filename, index) => ({
    order:    index + 1,
    filename,
    fullPath: path.join(migrationsDir, filename),
  }));

