  }

  console.log('\nDry-run complete. No SQL was executed.\n');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

run().catch(err => {
  console.error('\n[FATAL]', err);
  process.exit(1);
});

