// Configuration
// ---------------------------------------------------------------------------

/** Resolve the migrations directory from a CLI flag or fall back to default. */
function getMigrationsDir() {
  const flagIndex = process.argv.indexOf('--dir');
  if (flagIndex !== -1 && process.argv[flagIndex + 1]) {
    return path.resolve(process.argv[flagIndex + 1]);
  }
  return path.resolve(__dirname, 'migrations');
}

/** Resolve the .env file path from a CLI flag or fall back to .env.test. */
function getEnvFilePath() {
  const flagIndex = process.argv.indexOf('--env-file');
  if (flagIndex !== -1 && process.argv[flagIndex + 1]) {
    return path.resolve(process.argv[flagIndex + 1]);
  }
  return path.resolve(__dirname, '.env.test');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses a .env file and returns a plain object of key/value pairs.
 *
 * Supports:
 *   - KEY=value
 *   - KEY="quoted value"  /  KEY='quoted value'
 *   - Inline # comments
 *   - Blank lines and comment-only lines (# ...)
 *
 * Does NOT call process.env — values stay local to this script so that
 * nothing leaks into child processes or the broader environment.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value map.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const raw  = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  for (const rawLine of raw.split('\n')) {
    // Strip inline comments and surrounding whitespace.
    const line = rawLine.replace(/#.*$/, '').trim();

    if (!line || !line.includes('=')) continue;

    // Split only on the first '=' so values that contain '=' are preserved.
    const eqIndex = line.indexOf('=');
    const key     = line.slice(0, eqIndex).trim();
    let   value   = line.slice(eqIndex + 1).trim();

    // Strip optional surrounding quotes.
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    if (key) vars[key] = value;
  }

  return vars;
}

/**
 * Resolves DATABASE_URL from the env file, validates its presence, and
 * returns a redacted version safe to print.
 *
 * The redacted form keeps the protocol and host so engineers can confirm
 * the right server is targeted, but replaces credentials with '***' and
 * omits path/query details — consistent with how tools like Flyway,
 * golang-migrate, and Prisma log connection info.
 *
 * Example:
 *   postgres://admin:secret@db.internal:5432/production
 *   →  postgres://***@db.internal:5432
 *
 * @param {string} envFilePath - Absolute path to the .env file.
 * @returns {{ redacted: string }} Redacted connection details for logging.
 */
function resolveConnectionString(envFilePath) {
  const vars = parseEnvFile(envFilePath);

  if (!vars.DATABASE_URL) {
    throw new Error(
      `DATABASE_URL is not defined in env file: ${envFilePath}`
    );
  }

  const raw = vars.DATABASE_URL;

  // Parse with the built-in URL class — throws if the value is not a valid URL.
  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    throw new Error(
      `DATABASE_URL in ${envFilePath} is not a valid URL.`
    );
  }

  // Build a redacted string: protocol + masked credentials + host only.
  const redacted = `${parsed.protocol}//***@${parsed.host}`;

  return { redacted };
}

