/**
 * migrate.js
 *
 * Reads *.sql files from the ./migrations/ directory and logs each filename
 * it would apply, in lexicographic (version) order.
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./custom_migrations   # optional custom directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Resolve the migrations directory from a CLI flag or fall back to default. */
function resolveMigrationsDir() {
  const dirFlagIndex = process.argv.indexOf('--dir');
  if (dirFlagIndex !== -1) {
    const custom = process.argv[dirFlagIndex + 1];
    if (!custom || custom.startsWith('--')) {
      die('--dir requires a path argument, e.g. --dir ./my_migrations');
    }
    return path.resolve(custom);
  }
  return path.resolve(__dirname, 'migrations');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Print an error message and exit with a non-zero code. */
function die(message) {
  console.error(`[migrate] ERROR: ${message}`);
  process.exit(1);
}

/** Return true when a filename looks like a SQL migration file. */
function isSqlFile(filename) {
  return path.extname(filename).toLowerCase() === '.sql';
}

/**
 * Read all *.sql files from `dir`, sort them lexicographically (so numeric
 * prefixes like 001_, 002_ produce the correct order), and return the sorted
 * list of filenames (not full paths).
 */
function collectMigrations(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      die(`Migrations directory not found: ${dir}`);
    }
    die(`Could not read migrations directory: ${err.message}`);
  }

  const sqlFiles = entries.filter(isSqlFile);

  if (sqlFiles.length === 0) {
    return [];
  }

  // Lexicographic sort — relies on zero-padded numeric prefixes (e.g. 001_)
  // to guarantee version order.
  sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

  return sqlFiles;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function main() {
  const migrationsDir = resolveMigrationsDir();

  console.log(`[migrate] Migrations directory : ${migrationsDir}`);

  const migrations = collectMigrations(migrationsDir);

  if (migrations.length === 0) {
    console.log('[migrate] No SQL migration files found. Nothing to apply.');
    return;
  }

  console.log(`[migrate] Found ${migrations.length} migration(s) to apply:\n`);

  migrations.forEach((filename, index) => {
    const fullPath = path.join(migrationsDir, filename);
    const stats    = fs.statSync(fullPath);
    const sizeKb   = (stats.size / 1024).toFixed(2);

    console.log(
      `  [${String(index + 1).padStart(3, '0')}] ${filename}  (${sizeKb} KB)`
    );
  });

  console.log('\n[migrate] Dry run complete — no changes were made to the database.');
  console.log('[migrate] Remove the dry-run guard and plug in your DB client to apply migrations.');
}

main();

