-- Migration 003: Add role column to users
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role VARCHAR(50) NOT NULL DEFAULT 'user';

#!/usr/bin/env node
/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename (in lexicographic order) that would be applied.
 *
 * Naming convention expected:
 *   <version>_<description>.sql   e.g. 001_create_users.sql
 *
 * The script is intentionally read-only / dry-run: it discovers and
 * validates migration files without connecting to any database, making
 * it safe to run in any environment.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// Matches files like 001_create_users.sql — leading digits, underscore, name.
const VALID_NAME_RE = /^\d+_.+\.sql$/;

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when `filename` follows the expected naming convention.
 * @param {string} filename  - Bare filename (no directory component).
 * @returns {boolean}
 */
function isValidMigrationName(filename) {
  return VALID_NAME_RE.test(filename);
}

/**
 * Reads the migrations directory and returns a sorted array of SQL filenames.
 *
 * Sorting is lexicographic, which preserves numeric order as long as version
 * prefixes are zero-padded to the same width (e.g. 001, 002, … 099, 100).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of SQL filenames.
 * @throws {Error}     If the directory cannot be read.
 */
function getSortedMigrations(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  // Keep only .sql files, warn about anything else.
  const sqlFiles = entries.filter((entry) => {
    if (!entry.endsWith(SQL_EXTENSION)) {
      console.warn(`  [skip]  "${entry}" — not a .sql file, ignoring.`);
      return false;
    }
    return true;
  });

  // Validate naming convention, warn on violations but still include them.
  sqlFiles.forEach((filename) => {
    if (!isValidMigrationName(filename)) {
      console.warn(
        `  [warn]  "${filename}" does not follow the <version>_<name>.sql ` +
        `convention. It will be applied, but ordering may be unreliable.`
      );
    }
  });

  // Lexicographic sort — zero-padded numeric prefixes guarantee correct order.
  return sqlFiles.sort();
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner (dry run) ===\n');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  // ── 1. Discover migrations ──────────────────────────────────────────────────
  let migrations;
  try {
    migrations = getSortedMigrations(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (migrations.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  // ── 2. Log each file that would be applied ──────────────────────────────────
  console.log(`Found ${migrations.length} migration(s) to apply:\n`);

  migrations.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const number   = String(index + 1).padStart(3, '0');

    // Stat the file so we can surface any permission / access problems early.
    try {
      const stat = fs.statSync(filePath);
      const kb   = (stat.size / 1024).toFixed(2);
      console.log(`  [${number}] ${filename}  (${kb} KB)`);
    } catch (err) {
      console.error(`  [${number}] ${filename}  — ERROR: ${err.message}`);
    }
  });

  console.log('\n--- Dry run complete. No changes were made to the database. ---');
}

main();

