const MIGRATIONS_DIR  = path.resolve(__dirname, 'migrations');
const DEFAULT_ENV_FILE = path.resolve(__dirname, '.env.test');
const SQL_EXTENSION   = '.sql';

// Matches files like 001_create_users.sql — leading digits, underscore, name.
const VALID_NAME_RE = /^\d+_.+\.sql$/;

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when `filename` follows the expected naming convention.
 * @param {string} filename  - Bare filename (no directory component).
 * @returns {boolean}
 */
function isValidMigrationName(filename) {
  return VALID_NAME_RE.test(filename);
}

/**
 * Parses a .env-style file into a plain key/value object.
 *
 * Rules:
 *  - Lines beginning with # (optionally preceded by whitespace) are comments.
 *  - Blank lines are ignored.
 *  - The first `=` on a line separates key from value.
 *  - Surrounding whitespace on both key and value is stripped.
 *  - Inline comments (# …) are NOT stripped — values are taken verbatim so
 *    that special characters inside passwords are never silently truncated.
 *
 * @param {string} filePath - Absolute path to the env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw new Error(`Failed to read env file: ${err.message}`);
  }

  const result = {};
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue; // blank or comment

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // no '=' — not a valid assignment, skip

    const key   = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();
    if (key) result[key] = value;
  }
  return result;
}

/**
 * Reads DATABASE_URL from the given env file, validates it, and returns a
 * safe-to-log descriptor that contains only the host, port, and database name.
 * The password (and any other credentials) are intentionally omitted.
 *
 * @param {string} envFilePath - Absolute path to the env file.
 * @returns {{ raw: string, display: string }} 
 *   raw     — the original connection string (used internally, never logged).
 *   display — a redacted string safe to print: postgres://<host>:<port>/<db>
 * @throws {Error} If DATABASE_URL is missing or cannot be parsed.
 */
function resolveConnectionString(envFilePath) {
  const env = parseEnvFile(envFilePath);

  if (!env.DATABASE_URL) {
    throw new Error(
      `DATABASE_URL is not defined in ${envFilePath}`
    );
  }

  const raw = env.DATABASE_URL;

  // Parse the URL so we can extract only the safe parts.
  let parsed;
  try {
    parsed = new url.URL(raw);
  } catch {
    throw new Error(
      'DATABASE_URL is not a valid URL. ' +
      'Expected format: <protocol>://<user>:<password>@<host>:<port>/<database>'
    );
  }

  // Build a display string that omits credentials entirely.
  const port     = parsed.port || (parsed.protocol === 'postgres:' ? '5432' : '');
  const hostPart = port ? `${parsed.hostname}:${port}` : parsed.hostname;
  const dbName   = parsed.pathname.replace(/^\//, '') || '(default)';
  const display  = `${parsed.protocol}//${hostPart}/${dbName}`;

  return { raw, display };
}

