 * Reads the migrations directory and returns a sorted array of SQL filenames.
 *
 * Sorting is lexicographic, which preserves numeric order as long as version
 * prefixes are zero-padded to the same width (e.g. 001, 002, … 099, 100).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of SQL filenames.
 * @throws {Error}     If the directory cannot be read.
 */
function getSortedMigrations(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

