function main() {
  // Allow `--env <path>` to override the default .env.test location.
  const envFlagIndex = process.argv.indexOf('--env');
  const envFilePath  = envFlagIndex !== -1
    ? path.resolve(process.argv[envFlagIndex + 1])
    : DEFAULT_ENV_FILE;

