/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename in the order it would be applied (lexicographic / numeric order).
 *
 * Usage:
 *   node migrate.js
 *
 * Naming convention for migration files:
 *   <NNN>_<description>.sql   e.g. 001_create_users.sql
 *
 * Only files that match the *.sql glob are considered; any other files
 * present in the directory (e.g. README.md) are silently ignored.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when a directory entry is a regular *.sql file.
 *
 * @param {fs.Dirent} entry
 * @returns {boolean}
 */
function isSqlFile(entry) {
  return entry.isFile() && path.extname(entry.name).toLowerCase() === SQL_EXTENSION;
}

/**
 * Reads all *.sql files from `dirPath`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) determine the application order.
 *
 * @param {string} dirPath - Absolute path to the migrations directory.
 * @returns {string[]}     - Sorted array of SQL filenames (not full paths).
 * @throws {Error}         - When the directory cannot be read.
 */
function getSqlFiles(dirPath) {
  let entries;

  try {
    // withFileTypes gives us Dirent objects so we can call .isFile()
    entries = fs.readdirSync(dirPath, { withFileTypes: true });
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dirPath}`);
    }
    if (err.code === 'EACCES') {
      throw new Error(`Permission denied reading migrations directory: ${dirPath}`);
    }
    throw err;
  }

  return entries
    .filter(isSqlFile)
    .map(entry => entry.name)
    .sort(); // lexicographic sort — relies on numeric prefix convention
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log(`Migration runner`);
  console.log(`Directory : ${MIGRATIONS_DIR}`);
  console.log('─'.repeat(48));

  let files;
  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No SQL migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((filename, index) => {
    const step     = String(index + 1).padStart(2, '0');
    const fullPath = path.join(MIGRATIONS_DIR, filename);

    console.log(`  [${step}] ${filename}`);
    console.log(`       → ${fullPath}`);
  });

  console.log('\n' + '─'.repeat(48));
  console.log(`Done. ${files.length} migration(s) listed.`);
}

main();

