/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs the
 * filenames in the order they would be applied (lexicographic / numeric
 * prefix order).
 *
 * Usage:
 *   node migrate.js                  # dry-run: log filenames only
 *   node migrate.js --verbose        # also print each file's SQL content
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const args           = process.argv.slice(2);
const VERBOSE        = args.includes('--verbose');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when a filename is a candidate migration file.
 * Only plain files whose names end in ".sql" are accepted.
 *
 * @param {string}       name  - bare filename (e.g. "001_create_users.sql")
 * @param {fs.Dirent}    dirent
 * @returns {boolean}
 */
function isSqlFile(name, dirent) {
  return dirent.isFile() && name.toLowerCase().endsWith('.sql');
}

/**
 * Reads all SQL migration files from `dir`, sorts them, and returns an array
 * of objects describing each migration.
 *
 * @param {string} dir - absolute path to the migrations directory
 * @returns {{ index: number, filename: string, filepath: string }[]}
 */
function collectMigrations(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter((dirent) => isSqlFile(dirent.name, dirent))
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }))
    .map((dirent, idx) => ({
      index:    idx + 1,
      filename: dirent.name,
      filepath: path.join(dir, dirent.name),
    }));
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);
  console.log(`Mode                 : dry-run (no DB connection)\n`);

  // 1. Collect migration files
  const migrations = collectMigrations(MIGRATIONS_DIR);

  if (migrations.length === 0) {
    console.warn('No .sql migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s) to apply:\n`);

  // 2. Log each migration in order
  for (const { index, filename, filepath } of migrations) {
    console.log(`  [${String(index).padStart(3, '0')}] ${filename}`);

    // --verbose: also print the SQL content, indented for readability
    if (VERBOSE) {
      const sql = fs.readFileSync(filepath, 'utf8').trimEnd();
      const indented = sql
        .split('\n')
        .map((line) => `         ${line}`)
        .join('\n');
      console.log(indented);
      console.log(); // blank line between migrations
    }
  }

  console.log('\nDry-run complete. Pass --verbose to inspect SQL content.');
}

main();

