const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const args           = process.argv.slice(2);
const VERBOSE        = args.includes('--verbose');

// Allow --env-file=<path> to override the default env file.
const envFileArg = args.find((a) => a.startsWith('--env-file='));
const ENV_FILE   = path.resolve(
  __dirname,
  envFileArg ? envFileArg.slice('--env-file='.length) : '.env.test',
);

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parses a .env-style file and returns a plain object of key → value pairs.
 *
 * Supported syntax:
 *   KEY=value          plain value
 *   KEY="value"        double-quoted  (quotes are stripped)
 *   KEY='value'        single-quoted  (quotes are stripped)
 *   # comment          ignored
 *   (blank lines)      ignored
 *
 * Nothing is written to process.env — the caller decides what to do with the
 * returned object.
 *
 * @param {string} filePath - absolute path to the .env file
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue; // malformed line — skip silently

    const key = trimmed.slice(0, eqIdx).trim();
    let   val = trimmed.slice(eqIdx + 1).trim();

    // Strip matching surrounding quotes
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }

    if (key) result[key] = val;
  }

  return result;
}

/**
 * Resolves DATABASE_URL from the parsed env object and returns a sanitised
 * descriptor — { host, port, database } — safe to log without leaking secrets.
 *
 * Throws a descriptive error if the variable is missing or unparseable.
 *
 * @param {Record<string, string>} env
 * @returns {{ host: string, port: string, database: string }}
 */
function resolveConnectionInfo(env) {
  const raw = env['DATABASE_URL'];

  if (!raw || raw.trim() === '') {
    throw new Error('DATABASE_URL is not set in the env file.');
  }

  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    // URL constructor throws a TypeError for invalid URLs — do not include the
    // raw value in the error message to avoid leaking credentials.
    throw new Error('DATABASE_URL could not be parsed as a valid URL.');
  }

  const protocol = parsed.protocol.replace(/:$/, ''); // strip trailing colon
  const allowed  = ['postgres', 'postgresql', 'mysql', 'mariadb', 'mssql', 'sqlite'];
  if (!allowed.includes(protocol)) {
    throw new Error(
      `DATABASE_URL uses an unrecognised protocol "${protocol}". ` +
      `Expected one of: ${allowed.join(', ')}.`,
    );
  }

  return {
    protocol,
    host:     parsed.hostname,
    port:     parsed.port || defaultPort(protocol),
    database: parsed.pathname.replace(/^\//, '') || '(default)',
  };
}

/**
 * Returns the conventional default port for a given DB protocol.
 *
 * @param {string} protocol
 * @returns {string}
 */
function defaultPort(protocol) {
  const ports = {
    postgres:   '5432',
    postgresql: '5432',
    mysql:      '3306',
    mariadb:    '3306',
    mssql:      '1433',
    sqlite:     'N/A',
  };
  return ports[protocol] ?? 'unknown';
}

// ─── Main ─────────────────────────────────────────────────────────────────────

