/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (numeric-prefix) order.
 *
 * Usage:
 *   node migrate.js
 *
 * What it does:
 *  1. Scans ./migrations/ for files ending in .sql.
 *  2. Sorts them lexicographically so numeric prefixes (001_, 002_, …)
 *     define a deterministic execution order.
 *  3. Logs each filename as it would be applied — ready to be wired up to
 *     a real database client (see the `applyMigration` stub below).
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an alphabetically sorted list of .sql filenames found in `dir`.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basename only).
 * @throws {Error} If the directory cannot be read.
 */
function getMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
