-- Migration 003: Add role column to users
ALTER TABLE users
  ADD COLUMN IF NOT EXISTS role VARCHAR(50) NOT NULL DEFAULT 'member';

/**
 * migrate.js
 *
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * it would apply, in lexicographic (alphabetical) order.
 *
 * Conventions expected for migration files:
 *   - Must live directly inside ./migrations/
 *   - Must have a .sql extension
 *   - Should be prefixed with a zero-padded sequence number so that
 *     lexicographic order matches intended application order
 *     e.g. 001_create_users.sql, 002_create_posts.sql, …
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of .sql filenames found in `dir`, sorted lexicographically.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basenames only).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  return entries
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort(); // lexicographic — relies on numeric prefix convention
}

/**
 * Validates that a filename follows the expected naming convention:
 *   <digits>_<description>.sql
 *
 * Logs a warning for any file that does not match, but does not skip it.
 *
 * @param {string} filename
 */
function warnIfUnconventional(filename) {
  const CONVENTION = /^\d+_.+\.sql$/i;
  if (!CONVENTION.test(filename)) {
    console.warn(
      `  ⚠  Warning: "${filename}" does not follow the ` +
      `"<number>_<description>.sql" naming convention.`
    );
  }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

