/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename in the order it would be applied (ascending lexicographic order,
 * which matches the numeric prefix convention: 001_, 002_, …).
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql file inside `dir`, sorted in ascending order so that
 * migrations are applied lowest-numbered first (001 → 002 → 003 …).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basenames only).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  return entries
    .filter(entry => {
      // Only plain files with a .sql extension.
      const fullPath = path.join(dir, entry);
      return (
        path.extname(entry).toLowerCase() === '.sql' &&
        fs.statSync(fullPath).isFile()
      );
    })
    .sort(); // lexicographic ascending — relies on numeric prefix (001_, 002_, …)
}

/**
 * Simulates running each migration by logging the filename that *would* be
 * applied without actually executing any SQL.
 *
 * Replace the body of this function (or add logic after the log line) to wire
 * in a real database client (e.g. `pg`, `mysql2`, `better-sqlite3`, …).
 *
 * @param {string[]} files   - Sorted array of .sql filenames.
 * @param {string}   baseDir - Directory that contains the files.
 */
function applyMigrations(files, baseDir) {
  if (files.length === 0) {
    console.log('No migration files found — nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration(s) in: ${baseDir}\n`);
  console.log('Applying migrations:');
  console.log('─'.repeat(50));

  files.forEach((filename, index) => {
    const filePath = path.join(baseDir, filename);

    // ── Dry-run output ────────────────────────────────────────────────────
    console.log(`[${String(index + 1).padStart(3, '0')}] Applying: ${filename}`);

    // ── TODO: swap the block below in for real execution ──────────────────
    // const sql = fs.readFileSync(filePath, 'utf8');
    // await dbClient.query(sql);          // e.g. node-postgres
    // console.log(`      ✔  ${filename} applied successfully.`);
    // ─────────────────────────────────────────────────────────────────────
  });

  console.log('─'.repeat(50));
  console.log(`\nDone. ${files.length} migration(s) logged (dry-run).`);
}

// ─── Entry point ──────────────────────────────────────────────────────────────

(function main() {
  try {
    const sqlFiles = getSqlFiles(MIGRATIONS_DIR);
    applyMigrations(sqlFiles, MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Migration error: ${err.message}`);
    process.exit(1);
  }
})();

