/**
 * Parses a .env file and returns its key/value pairs as a plain object.
 *
 * Handles:
 *  - `KEY=value` assignments (with optional surrounding whitespace)
 *  - Quoted values:  KEY="value"  or  KEY='value'  (quotes are stripped)
 *  - Inline comments after a space:  KEY=value  # comment
 *  - Full-line comments (#) and blank lines (both are skipped)
 *
 * This intentionally avoids `dotenv` so the script stays dependency-free.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value map.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw new Error(`Failed to read env file: ${err.message}`);
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and full-line comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // no '=' → not a valid assignment

    const key = trimmed.slice(0, eqIndex).trim();
    let   val = trimmed.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes (single or double).
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    } else {
      // Strip inline comment (space + '#' marks the start of a comment).
      const commentMatch = val.match(/^(.*?)\s+#.*$/);
      if (commentMatch) val = commentMatch[1].trim();
    }

    result[key] = val;
  }

  return result;
}

