 * Extracts DATABASE_URL from the env map, validates that it is present, and
 * returns a redacted summary object — never the raw URL or its password.
 *
 * @param {Record<string, string>} env - Parsed environment variables.
 * @returns {{ protocol: string, host: string, port: string, database: string }}
 * @throws {Error} If DATABASE_URL is missing or cannot be parsed.
