/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs the
 * filename of each migration it would apply, in lexicographic (numeric)
 * order.
 *
 * Usage:
 *   node migrate.js
 *
 * Exit codes:
 *   0 – success (even when no migrations are found)
 *   1 – unrecoverable error (e.g. migrations directory is missing)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when `filename` is a plain file whose name ends with `.sql`.
 * Directories named "something.sql" are intentionally excluded.
 *
 * @param {string} filename - Bare filename (no directory component).
 * @returns {boolean}
 */
function isSqlFile(filename) {
  if (!filename.toLowerCase().endsWith(SQL_EXTENSION)) return false;

  const fullPath = path.join(MIGRATIONS_DIR, filename);
  try {
    return fs.statSync(fullPath).isFile();
  } catch {
    // If stat fails for any reason, skip the entry.
    return false;
  }
}

/**
 * Reads and validates the migrations directory, then returns the sorted list
 * of SQL filenames that would be applied.
 *
 * Sorting is lexicographic, which aligns with the conventional
 * `NNN_description.sql` numbering scheme (e.g. 001, 002, …, 010).
 *
 * @returns {string[]} Sorted array of SQL filenames.
 */
function resolveMigrationFiles() {
  // Guard: directory must exist.
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    throw new Error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
  }

  const stat = fs.statSync(MIGRATIONS_DIR);
  if (!stat.isDirectory()) {
    throw new Error(`Expected a directory at: ${MIGRATIONS_DIR}`);
  }

  const entries = fs.readdirSync(MIGRATIONS_DIR);

  const sqlFiles = entries.filter(isSqlFile);

  // Lexicographic sort — works correctly for zero-padded numeric prefixes.
  sqlFiles.sort((a, b) => a.localeCompare(b));

  return sqlFiles;
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log(`Migration runner starting…`);
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  let migrationFiles;

  try {
    migrationFiles = resolveMigrationFiles();
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (migrationFiles.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  migrationFiles.forEach((filename, index) => {
    const position    = String(index + 1).padStart(String(migrationFiles.length).length, '0');
    const filePath    = path.join(MIGRATIONS_DIR, filename);
    const { size }    = fs.statSync(filePath);

    console.log(`  [${position}/${migrationFiles.length}] ${filename}  (${size} bytes)`);
  });

  console.log('\nDry run complete. No changes were made to the database.');
}

main();

