 *
 * Does NOT evaluate variable substitution or shell expansions.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const raw  = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  for (const rawLine of raw.split('\n')) {
    const line = rawLine.trim();

    // Skip blank lines and full-line comments.
    if (line === '' || line.startsWith('#')) continue;

    // A valid assignment must contain '='.
    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    if (key === '') continue;

    // Everything after the first '=', before any trailing inline comment.
    let value = line.slice(eqIndex + 1);

    // Strip inline comment: space/tab + '#' + anything.
    value = value.replace(/\s+#.*$/, '');

    // Strip matched surrounding quotes (" or ').
    value = value.trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
