-- Migration 003: Add role column to users
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role VARCHAR(50) NOT NULL DEFAULT 'member';

/**
 * migrate.js
 *
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * it would apply, in ascending lexicographic order.
 *
 * Usage:
 *   node migrate.js
 *
 * Conventions expected for migration files:
 *   - Located in ./migrations/ (relative to this script)
 *   - Named with a numeric prefix so lexicographic order matches
 *     intended application order, e.g. 001_create_users.sql
 *   - Extension must be .sql (other files are ignored)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns a sorted array of .sql filenames found in the given directory.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted filenames (not full paths).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    if (err.code === 'ENOTDIR') {
      throw new Error(`Path is not a directory: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(name => {
      // Keep only regular .sql files; skip sub-directories and other extensions.
      const fullPath = path.join(dir, name);
      return (
        path.extname(name).toLowerCase() === SQL_EXTENSION &&
        fs.statSync(fullPath).isFile()
      );
    })
    .sort(); // Lexicographic sort — relies on numeric prefix convention.
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log(`Migration runner`);
  console.log(`Migrations directory: ${MIGRATIONS_DIR}`);
  console.log('─'.repeat(50));

  let sqlFiles;

  try {
    sqlFiles = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (sqlFiles.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

  sqlFiles.forEach((filename, index) => {
    const step = String(index + 1).padStart(3, '0');
    console.log(`  [${step}] ${filename}`);
  });

  console.log('\n─'.repeat(50));
  console.log('Done. (dry-run — no database connection made)');
}

main();

