 * 2. Reads all *.sql files from the ./migrations/ directory and logs each
 *    filename in the order it would be applied (ascending lexicographic order,
 *    which matches the numeric prefix convention: 001_, 002_, …).
 *
 * Usage:
 *   node migrate.js
 *
 * Exit codes:
 *   0 — completed successfully (even if no migrations were found)
 *   1 — unrecoverable error (missing env file, missing DATABASE_URL,
 *                            malformed URL, or missing migrations directory)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE       = path.resolve(__dirname, '.env.test');
const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parses a .env file into a plain key/value object.
 * Handles:
 *   - Full-line comments (#)
 *   - Blank lines
 *   - Optional surrounding quotes on values
 *   - Inline comments are intentionally NOT stripped (values are used as-is)
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch {
    throw new Error(`Cannot read env file: ${filePath}`);
  }

  const vars = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blanks and full-line comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;                    // no '=' → skip

    const key   = trimmed.slice(0, eqIndex).trim();
    let   value = trimmed.slice(eqIndex + 1).trim();

    // Strip matching outer quotes if present.
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    vars[key] = value;
  }

  return vars;
}

/**
 * Resolves DATABASE_URL from the env file and returns a safe-to-log summary
 * of the connection target (protocol, host, port, database).
 * The username and password are intentionally excluded from the returned
 * string so that credentials are never written to stdout/logs.
 *
 * @param {string} envFilePath - Absolute path to the .env file.
 * @returns {{ url: string, display: string }}
 *   url     — the raw DATABASE_URL value (used only internally, not logged)
 *   display — a redacted string safe to print, e.g.
 *             "postgres://db.internal:5432/production"
 */
function resolveConnectionString(envFilePath) {
  const env = parseEnvFile(envFilePath);

  if (!env.DATABASE_URL) {
    throw new Error(`DATABASE_URL is not defined in ${envFilePath}`);
  }

  const rawUrl = env.DATABASE_URL;

  // Parse with the built-in WHATWG URL API so we never do fragile
  // regex surgery on the raw string.
  let parsed;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(`DATABASE_URL in ${envFilePath} is not a valid URL`);
  }

  // Build a redacted display string: omit username and password entirely.
  const port    = parsed.port || defaultPortFor(parsed.protocol);
  const display = `${parsed.protocol}//${parsed.hostname}:${port}${parsed.pathname}`;

  return { url: rawUrl, display };
}

/**
 * Returns the conventional default port for a given DB protocol string.
 *
 * @param {string} protocol - e.g. "postgres:" | "mysql:" | "mongodb:"
 * @returns {string}
 */
function defaultPortFor(protocol) {
  const defaults = {
    'postgres:':  '5432',
    'postgresql:': '5432',
    'mysql:':     '3306',
    'mongodb:':   '27017',
  };
  return defaults[protocol] ?? '(unknown port)';
}

/**
 * Validates that `dir` exists and is a directory.
 * Throws a descriptive error when the check fails.
 *
 * @param {string} dir - Path to validate.
 */
function assertDirectory(dir) {
  let stat;
  try {
    stat = fs.statSync(dir);
  } catch {
    throw new Error(`Migrations directory not found: ${dir}`);
  }
  if (!stat.isDirectory()) {
    throw new Error(`Expected a directory but found a file at: ${dir}`);
  }
}

/**
 * Returns every *.sql file inside `dir`, sorted in ascending order so that
 * numeric prefixes (001_, 002_, …) are applied in the correct sequence.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of full file paths.
 */
function getSqlFiles(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry   => entry.name)
    .sort()                        // lexicographic sort honours the NNN_ prefix
    .map(name    => path.join(dir, name));
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');

  // ── Step 1: Resolve & simulate the database connection ──────────────────────

  let connectionDisplay;
  try {
    const conn = resolveConnectionString(ENV_FILE);
    connectionDisplay = conn.display;
    // conn.url is intentionally never passed to console.log — it contains
    // credentials.  Only the redacted display string is printed.
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log(`Env file             : ${ENV_FILE}`);
  console.log(`Connecting to        : ${connectionDisplay}`);
  console.log(`Connection status    : OK (simulated)\n`);

  // ── Step 2: Validate the migrations directory ────────────────────────────────

  try {
    assertDirectory(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);

  // ── Step 3: Collect SQL files in application order ───────────────────────────

  const files = getSqlFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log('\nNo migration files found. Nothing to apply.');
    return;
  }

  console.log(`Migrations found     : ${files.length}\n`);

  // ── Step 4: Log each file in the order it would be applied ──────────────────

  files.forEach((filePath, index) => {
    const filename = path.basename(filePath);
    console.log(`  [${String(index + 1).padStart(3, '0')}] Applying: ${filename}`);
  });

  console.log('\nAll migrations logged successfully.');
  console.log('(Replace the simulated connection with a real DB client to execute each file.)');
}

main();

