 *   node migrate.js --run     # executes SQL against the database
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const DRY_RUN        = !process.argv.includes('--run');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an alphabetically sorted list of absolute paths for every
 * *.sql file found directly inside `dir`.  Throws if the directory
 * does not exist or cannot be read.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]}  Sorted array of absolute file paths.
 */
function collectMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort(); // lexicographic sort preserves 001_, 002_, … ordering

  if (sqlFiles.length === 0) {
    throw new Error(`No *.sql migration files found in: ${dir}`);
  }

  return sqlFiles.map(name => path.join(dir, name));
}

/**
 * Reads a migration file and returns its contents as a UTF-8 string.
 *
 * @param {string} filePath - Absolute path to the SQL file.
 * @returns {string}
 */
function readMigration(filePath) {
  return fs.readFileSync(filePath, 'utf8');
}

/**
 * Applies a single migration.  In dry-run mode this is a no-op;
 * replace the body of the `else` branch with your real database
 * driver call (e.g. pg, mysql2, better-sqlite3, …).
 *
 * @param {string} filePath - Absolute path to the SQL file.
 * @param {string} sql      - The SQL to execute.
 * @param {boolean} dryRun  - When true, skip actual execution.
 * @returns {Promise<void>}
 */
async function applyMigration(filePath, sql, dryRun) {
  if (dryRun) {
    // Nothing to execute — logging is handled by the caller.
    return;
  }

  // ── Replace this block with your real database driver ──────────────────────
  // Example using the `pg` package:
  //
  //   const { Client } = require('pg');
  //   const client = new Client({ connectionString: process.env.DATABASE_URL });
  //   await client.connect();
  //   try {
  //     await client.query(sql);
  //   } finally {
  //     await client.end();
  //   }
  //
  // ───────────────────────────────────────────────────────────────────────────
  throw new Error(
    'applyMigration: no database driver configured. ' +
    'Add your driver code or run in dry-run mode (omit --run).'
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────

async function main() {
  console.log('='.repeat(60));
  console.log('  Database Migration Runner');
  console.log('='.repeat(60));
  console.log(`  Migrations dir : ${MIGRATIONS_DIR}`);
  console.log(`  Mode           : ${DRY_RUN ? 'dry-run (pass --run to execute)' : 'LIVE — SQL will be executed'}`);
  console.log('='.repeat(60));
  console.log();

  // 1. Discover migration files.
  let migrationPaths;
  try {
    migrationPaths = collectMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log(`Found ${migrationPaths.length} migration(s):\n`);

  // 2. Iterate in order, log each file, then apply it.
  let applied = 0;
  let failed  = 0;

  for (const filePath of migrationPaths) {
    const filename = path.basename(filePath);
    const index    = migrationPaths.indexOf(filePath) + 1;
    const prefix   = `[${String(index).padStart(3, '0')}/${String(migrationPaths.length).padStart(3, '0')}]`;

    process.stdout.write(`${prefix} ${filename} … `);

    try {
      const sql = readMigration(filePath);
      await applyMigration(filePath, sql, DRY_RUN);

      const outcome = DRY_RUN ? 'would apply' : 'applied';
      console.log(outcome);
      applied++;
    } catch (err) {
      console.log('FAILED');
      console.error(`         └─ ${err.message}`);
      failed++;

      // Stop on the first failure so later migrations are not run
      // against a potentially inconsistent schema.
      break;
    }
  }

  // 3. Summary.
  console.log();
  console.log('─'.repeat(60));

  if (failed > 0) {
    console.log(`  Result  : ${applied} migration(s) processed, 1 FAILED — halted.`);
    console.log('─'.repeat(60));
    process.exit(1);
  } else {
    const verb = DRY_RUN ? 'ready to apply' : 'applied';
    console.log(`  Result  : ${applied} migration(s) ${verb} successfully.`);
    console.log('─'.repeat(60));
  }
}

main();

