/**
 * migrate.js
 *
 * Database migration runner.
 *
 * Discovers every *.sql file inside ./migrations/, sorts them in
 * lexicographic (alphabetical) order — which matches the numeric
 * prefix convention (001_, 002_, …) — and logs each filename it
