    const parsed = new URL(url);
    // Reconstruct without username or password.
    return `${parsed.protocol}//${parsed.hostname}${parsed.port ? `:${parsed.port}` : ''}${parsed.pathname}`;
  } catch {
    return '<unparseable URL>';
  }
}

/**
 * Returns an alphabetically sorted list of absolute paths for every
 * *.sql file found directly inside `dir`.  Throws if the directory
 * does not exist or cannot be read.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]}  Sorted array of absolute file paths.
 */
function collectMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort(); // lexicographic sort preserves 001_, 002_, … ordering

  if (sqlFiles.length === 0) {
    throw new Error(`No *.sql migration files found in: ${dir}`);
  }

  return sqlFiles.map(name => path.join(dir, name));
}

