 * Applies a single migration.  In dry-run mode this is a no-op;
 * replace the body of the `else` branch with your real database
 * driver call (e.g. pg, mysql2, better-sqlite3, …).
 *
 * @param {string} filePath - Absolute path to the SQL file.
 * @param {string} sql      - The SQL to execute.
 * @param {boolean} dryRun  - When true, skip actual execution.
 * @returns {Promise<void>}
 */
async function applyMigration(filePath, sql, dryRun) {
  if (dryRun) {
    // Nothing to execute — logging is handled by the caller.
    return;
  }

  // ── Replace this block with your real database driver ──────────────────────
  // Example using the `pg` package:
  //
  //   const { Client } = require('pg');
  //   const client = new Client({ connectionString: process.env.DATABASE_URL });
  //   await client.connect();
  //   try {
  //     await client.query(sql);
  //   } finally {
  //     await client.end();
  //   }
  //
  // ───────────────────────────────────────────────────────────────────────────
  throw new Error(
    'applyMigration: no database driver configured. ' +
    'Add your driver code or run in dry-run mode (omit --run).'
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────

async function main() {
  console.log('='.repeat(60));
  console.log('  Database Migration Runner');
  console.log('='.repeat(60));
  console.log(`  Migrations dir : ${MIGRATIONS_DIR}`);
  console.log(`  Env file       : ${ENV_FILE}`);
  console.log(`  Mode           : ${DRY_RUN ? 'dry-run (pass --run to execute)' : 'LIVE — SQL will be executed'}`);
  console.log('='.repeat(60));
  console.log();

  // 1. Resolve the database connection string.
  let connectionUrl;
  try {
    const { url, envSource } = resolveConnectionString();
    connectionUrl = url; // retained for driver calls in --run mode

    // Log a safe summary — host, port, and database name only.
    // The password and username are intentionally omitted.
    console.log(`  [DB] Connection string loaded from ${envSource}`);
    console.log(`  [DB] Target: ${safeConnectionSummary(connectionUrl)}`);
    console.log(`  [DB] Connected successfully (simulated)`);
    console.log();
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  // 2. Discover migration files.
  let migrationPaths;
  try {
    migrationPaths = collectMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log(`Found ${migrationPaths.length} migration(s):\n`);

  // 3. Iterate in order, log each file, then apply it.
  let applied = 0;
  let failed  = 0;

  for (const filePath of migrationPaths) {
    const filename = path.basename(filePath);
    const index    = migrationPaths.indexOf(filePath) + 1;
    const prefix   = `[${String(index).padStart(3, '0')}/${String(migrationPaths.length).padStart(3, '0')}]`;

    process.stdout.write(`${prefix} ${filename} … `);

    try {
      const sql = readMigration(filePath);
      await applyMigration(filePath, sql, DRY_RUN);

      const outcome = DRY_RUN ? 'would apply' : 'applied';
      console.log(outcome);
      applied++;
    } catch (err) {
      console.log('FAILED');
      console.error(`         └─ ${err.message}`);
      failed++;

      // Stop on the first failure so later migrations are not run
      // against a potentially inconsistent schema.
      break;
    }
  }

