-- Migration 003: Add role column to users
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role VARCHAR(50) NOT NULL DEFAULT 'user';

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (alphabetical) order.
 *
 * Naming convention for migration files:
 *   <NNN>_<description>.sql   e.g. 001_create_users.sql
 *
 * The numeric prefix guarantees a deterministic, repeatable order.
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when a filename is a valid migration file:
 *   • ends with .sql
 *   • starts with at least one digit (e.g. "001_", "1_")
 */
function isMigrationFile(filename) {
  return (
    path.extname(filename).toLowerCase() === SQL_EXTENSION &&
    /^\d+/.test(filename)
  );
}

/**
 * Extracts the leading numeric prefix from a migration filename so files can
 * be sorted numerically rather than lexicographically (preventing "10" < "9").
 *
 * e.g. "002_create_sessions.sql" → 2
 */
function migrationOrder(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : Infinity;
}

/**
 * Reads the migrations directory and returns all valid migration filenames
 * sorted in ascending numeric order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of migration filenames.
 */
function getMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(isMigrationFile)
    .sort((a, b) => {
      const orderDiff = migrationOrder(a) - migrationOrder(b);
      // Fall back to plain string comparison when prefixes are identical
      return orderDiff !== 0 ? orderDiff : a.localeCompare(b);
    });
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log(`Migrations directory : ${MIGRATIONS_DIR}\n`);

  const files = getMigrationFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log('No migration files found — nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((filename, index) => {
    const filePath    = path.join(MIGRATIONS_DIR, filename);
    const stat        = fs.statSync(filePath);
    const sizeKB      = (stat.size / 1024).toFixed(2);
    const position    = String(index + 1).padStart(String(files.length).length, '0');

    console.log(`  [${position}/${files.length}] ${filename}  (${sizeKB} KB)`);
  });

  console.log('\nDry-run complete. No changes were made to the database.');
}

main();

