// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR  = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION   = '.sql';
const DEFAULT_ENV_FILE = '.env.test';

// ─── CLI argument parsing ─────────────────────────────────────────────────────

/**
 * Parses the argv array for a named flag and returns its value, or the
 * supplied default when the flag is absent.
 *
 * e.g. ["--env", ".env.staging"]  →  ".env.staging"
 *
 * @param {string[]} argv
 * @param {string}   flag
 * @param {string}   defaultValue
 * @returns {string}
 */
function getArgValue(argv, flag, defaultValue) {
  const idx = argv.indexOf(flag);
  if (idx !== -1 && argv[idx + 1] !== undefined) {
    return argv[idx + 1];
  }
  return defaultValue;
}

// ─── Env-file parsing ─────────────────────────────────────────────────────────

/**
 * Parses a .env file into a plain key/value object.
 *
 * Supported line formats:
 *   KEY=value
 *   KEY="quoted value"
 *   KEY='quoted value'
 *   # comment lines and blank lines are ignored
 *
 * @param {string} filePath - Absolute path to the env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const vars = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = trimmed.slice(0, eqIdx).trim();
    let   value = trimmed.slice(eqIdx + 1).trim();

    // Strip matching surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    vars[key] = value;
  }

  return vars;
}

// ─── Connection-string helpers ────────────────────────────────────────────────

/**
 * Resolves and validates DATABASE_URL from a parsed env object.
 *
 * Throws a descriptive error when the key is absent or its value is empty.
 *
 * @param {Record<string, string>} env
 * @returns {string} The raw connection string.
 */
function resolveDatabaseUrl(env) {
  const url = env['DATABASE_URL'];
  if (!url || url.trim() === '') {
    throw new Error(
      'DATABASE_URL is not set or is empty in the env file.'
    );
  }
  return url.trim();
