      `"${redactPassword(connectionString)}"`
    );
  }

  const redacted = redactPassword(connectionString);
  console.log(`  Connected to database : ${redacted}`);
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  // ── 1. Resolve env file path from CLI args ──────────────────────────────────
  const envFileName = getArgValue(process.argv.slice(2), '--env', DEFAULT_ENV_FILE);
  const envFilePath = path.resolve(__dirname, envFileName);

