/**
 * migrate.js
 *
 * Reads all .sql files from the ./migrations/ directory and logs each
 * filename in the order it would be applied (ascending lexicographic order,
 * which matches the numeric prefix convention: 001_, 002_, …).
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dry-run   (default behaviour — logs only, no DB calls)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every .sql filename inside `dir`, sorted in ascending order so that
 * numerically-prefixed files (001_…, 002_…) are applied in the correct sequence.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basename only).
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith(SQL_EXTENSION))
    .map(entry => entry.name)
    .sort(); // lexicographic sort — relies on the numeric prefix (001_, 002_, …)

  return sqlFiles;
}

/**
 * Validates that a filename follows the expected naming convention:
 * `<digits>_<description>.sql`  e.g. `001_create_users_table.sql`
 *
 * Logs a warning for any file that does not match so operators can fix it
 * before a real run touches the database.
 *
 * @param {string} filename
 * @returns {boolean}
 */
function isValidMigrationName(filename) {
  return /^\d+_.+\.sql$/.test(filename);
}

// ─── Core logic ───────────────────────────────────────────────────────────────

/**
 * Main entry-point.  Discovers migration files, validates their names, and
 * logs the ordered list of files that *would* be applied.
 */
function runMigrations() {
  console.log('='.repeat(60));
  console.log('  Database Migration Runner (dry-run / planning mode)');
  console.log('='.repeat(60));
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);
  console.log('');

  // 1. Discover files
  let files;
  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('[INFO] No .sql migration files found. Nothing to apply.');
    return;
  }

  // 2. Validate names and warn about any that look wrong
  const invalidFiles = files.filter(f => !isValidMigrationName(f));
  if (invalidFiles.length > 0) {
    console.warn('[WARN] The following files do not follow the expected naming');
    console.warn('       convention (<digits>_<description>.sql) and will be');
    console.warn('       skipped in a real run:');
    invalidFiles.forEach(f => console.warn(`         - ${f}`));
    console.warn('');
  }

  const validFiles = files.filter(isValidMigrationName);

  // 3. Log the ordered plan
  console.log(`Found ${validFiles.length} migration(s) to apply, in order:\n`);

  validFiles.forEach((filename, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, filename);
    const stats    = fs.statSync(fullPath);
    const sizeKB   = (stats.size / 1024).toFixed(2);

    console.log(
      `  [${String(index + 1).padStart(3, '0')}] ${filename}  (${sizeKB} KB)`
    );
  });

  console.log('');
  console.log('-'.repeat(60));
  console.log('[DRY-RUN] No changes were made to the database.');
  console.log('          Remove the dry-run guard and add your DB client');
  console.log('          to execute these migrations for real.');
  console.log('='.repeat(60));
}

// ─── Entry point ──────────────────────────────────────────────────────────────

runMigrations();

