 * scoped to the returned object and are never injected into the process.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const raw     = fs.readFileSync(filePath, 'utf8');
  const result  = {};
  const LINE_RE = /^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/;

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and full-line comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const match = trimmed.match(LINE_RE);
    if (!match) continue;

    const key   = match[1];
    let   value = match[2];

    // Strip wrapping quotes (keeping the content between them)
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    } else {
      // Strip trailing inline comment: VALUE  # comment
      const commentIdx = value.indexOf(' #');
      if (commentIdx !== -1) value = value.slice(0, commentIdx).trim();
    }

    result[key] = value;
  }

  return result;
}

