/**
 * Parses a postgres:// connection URL and returns a sanitised descriptor
 * that is safe to log — the password is always replaced with "***".
 *
 * Returns null if the value is missing or cannot be parsed as a URL so the
 * caller can surface a clear error instead of leaking a partial credential.
 *
 * @param {string|undefined} rawUrl
 * @returns {{ protocol: string, user: string, host: string, port: string,
 *             database: string, redacted: string } | null}
 */
function parseConnectionString(rawUrl) {
  if (!rawUrl || !rawUrl.trim()) return null;

  let parsed;
  try {
    parsed = new URL(rawUrl);
  } catch {
    return null;
  }

  return {
    protocol : parsed.protocol.replace(':', ''),   // e.g. "postgres"
    user     : parsed.username || '(none)',
    host     : parsed.hostname,
    port     : parsed.port     || '5432',
    database : parsed.pathname.replace(/^\//, '') || '(none)',
