 * migrate.js — Database migration runner
 *
 * Reads every *.sql file from the ./migrations/ directory and logs
 * each filename it would apply, in ascending (alphabetical) order.
 *
 * Naming convention expected:
 *   <NNN>_<description>.sql   e.g.  001_create_users.sql
 *
 * Exit codes:
 *   0 — success (or nothing to do)
 *   1 — fatal error (directory missing, unreadable file, etc.)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when a filename looks like a valid, numbered migration.
 * Valid examples : 001_create_users.sql, 042_add_index.sql
 * Invalid examples: .DS_Store, README.md, _draft.sql
 *
 * @param {string} filename
 * @returns {boolean}
 */
function isMigrationFile(filename) {
  return (
    path.extname(filename).toLowerCase() === SQL_EXTENSION &&
    /^\d+/.test(filename) // must start with at least one digit
  );
}

/**
 * Compares two migration filenames by their leading numeric prefix so that
 * '002_...' always sorts before '010_...' regardless of string order.
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function byMigrationOrder(a, b) {
  const numA = parseInt(a, 10);
  const numB = parseInt(b, 10);

  if (numA !== numB) return numA - numB;

  // Fall back to plain lexicographic order when prefixes are identical.
  return a.localeCompare(b);
}

// ─── Core logic ───────────────────────────────────────────────────────────────

/**
 * Discovers, validates, and (dry-)applies every SQL migration in order.
 */
function runMigrations() {
  // 1. Verify the migrations directory exists and is accessible.
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`[migrate] ERROR: Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const stat = fs.statSync(MIGRATIONS_DIR);
  if (!stat.isDirectory()) {
    console.error(`[migrate] ERROR: Path is not a directory: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // 2. Read directory entries.
  let entries;
  try {
    entries = fs.readdirSync(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[migrate] ERROR: Could not read migrations directory — ${err.message}`);
    process.exit(1);
  }

  // 3. Filter to valid migration files only, then sort them.
  const migrationFiles = entries
    .filter(isMigrationFile)
    .sort(byMigrationOrder);

  if (migrationFiles.length === 0) {
    console.log('[migrate] No migration files found. Nothing to apply.');
    return;
  }

  // 4. Log a summary header.
  console.log(`[migrate] Found ${migrationFiles.length} migration(s) in: ${MIGRATIONS_DIR}`);
  console.log('[migrate] Applying migrations in order:\n');

  // 5. Iterate and (dry-)apply each migration.
  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);

    // Confirm the entry is a regular file before touching it.
    const fileStat = fs.statSync(filePath);
    if (!fileStat.isFile()) {
      console.warn(`[migrate] SKIP  [${index + 1}/${migrationFiles.length}] ${filename} — not a regular file`);
      return;
    }

    // Read the file contents so we can surface any I/O problems early,
    // before a real DB connection would be attempted.
    let sql;
    try {
      sql = fs.readFileSync(filePath, 'utf8');
    } catch (err) {
      console.error(`[migrate] ERROR: Could not read ${filename} — ${err.message}`);
      process.exit(1);
    }

    const lineCount = sql.split('\n').length;

    // Log the migration that *would* be applied.
    // Replace this comment with your real DB execution call, e.g.:
    //   await db.query(sql);
    console.log(
      `[migrate] APPLY [${String(index + 1).padStart(2, '0')}/${migrationFiles.length}] ` +
      `${filename}  (${lineCount} line${lineCount === 1 ? '' : 's'})`
    );
  });

  console.log('\n[migrate] Done — all migrations logged successfully.');
}

// ─── Entry point ──────────────────────────────────────────────────────────────

runMigrations();

