 *
 * Handles:
 *   - KEY=value
 *   - KEY="quoted value"  /  KEY='quoted value'
 *   - Inline # comments after the value
 *   - Whole-line # comments and blank lines (both are skipped)
 *
 * Returns a plain object of { KEY: 'value' } pairs.
 * Does NOT mutate process.env — callers decide what to do with the result.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {{ [key: string]: string }}
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    console.error(`[migrate] ERROR: Could not read env file (${filePath}) — ${err.message}`);
    process.exit(1);
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and full-line comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Only process lines that contain an '=' sign.
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const key   = trimmed.slice(0, eqIndex).trim();
    let   value = trimmed.slice(eqIndex + 1).trim();

    // Strip surrounding quotes (single or double).
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    } else {
      // Remove any trailing inline comment (e.g. VALUE=foo # comment).
      const commentIndex = value.indexOf(' #');
      if (commentIndex !== -1) {
        value = value.slice(0, commentIndex).trim();
      }
    }

    if (key) result[key] = value;
  }

  return result;
}

