 * asterisks so it is safe to print to the console.
 *
 * Input : postgres://admin:s3cr3t@db.host:5432/mydb
 * Output: postgres://admin:********@db.host:5432/mydb
 *
 * If the URL cannot be parsed the original string is returned unchanged.
 *
 * @param {string} url
 * @returns {string}
 */
function redactConnectionString(url) {
  try {
    const parsed   = new URL(url);
    parsed.password = parsed.password ? '********' : '';
    return parsed.toString();
  } catch {
    return url; // not a valid URL — return as-is, don't crash
  }
}

/**
 * Resolves and validates DATABASE_URL from the env file.
 *
 * @returns {string} The validated, raw connection string.
 */
function resolveConnectionString() {
  console.log(`[migrate] Reading env file: ${ENV_FILE}`);

  if (!fs.existsSync(ENV_FILE)) {
    console.error(`[migrate] ERROR: Env file not found: ${ENV_FILE}`);
    process.exit(1);
  }

  const env          = parseEnvFile(ENV_FILE);
  const databaseUrl  = env['DATABASE_URL'];

  if (!databaseUrl) {
    console.error('[migrate] ERROR: DATABASE_URL is not defined in the env file.');
    process.exit(1);
  }

  // Basic sanity-check: must look like a connection URL.
  if (!databaseUrl.includes('://')) {
    console.error('[migrate] ERROR: DATABASE_URL does not appear to be a valid connection string.');
    process.exit(1);
  }

  // Log a redacted form — never print the raw password to the console.
  const redacted = redactConnectionString(databaseUrl);
  console.log(`[migrate] DATABASE_URL resolved: ${redacted}`);
  console.log('[migrate] Connected to database successfully.\n');

