const fs   = require("fs");
const path = require("path");

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.join(__dirname, "migrations");
const SQL_EXTENSION  = ".sql";

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when a directory entry is a regular *.sql file.
 *
 * @param {fs.Dirent} entry
 * @returns {boolean}
 */
function isSqlFile(entry) {
  return entry.isFile() && path.extname(entry.name).toLowerCase() === SQL_EXTENSION;
}

/**
 * Reads all *.sql files from `dirPath`, sorts them lexicographically
 * (so numeric prefixes such as 001_, 002_ … produce the correct order),
 * and returns an array of absolute file paths.
 *
 * Throws a descriptive error when the directory cannot be accessed.
 *
 * @param {string} dirPath  Absolute path to the migrations directory.
 * @returns {string[]}      Sorted absolute paths.
 */
function collectMigrationFiles(dirPath) {
  let entries;

  try {
    // `withFileTypes: true` gives us Dirent objects so we can call .isFile()
    entries = fs.readdirSync(dirPath, { withFileTypes: true });
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Migrations directory not found: ${dirPath}`);
    }
    if (err.code === "EACCES") {
      throw new Error(`Permission denied reading directory: ${dirPath}`);
    }
    throw err; // re-throw anything unexpected
  }

  return entries
    .filter(isSqlFile)
    .map((entry) => entry.name)
    .sort() // lexicographic sort — relies on numeric prefixes (001_, 002_, …)
    .map((name) => path.join(dirPath, name));
}

/**
 * Reads a migration file from disk and returns its SQL content as a string.
 *
 * @param {string} filePath  Absolute path to a *.sql file.
 * @returns {string}
 */
function readMigrationFile(filePath) {
  return fs.readFileSync(filePath, "utf8");
}

