/**
 * Main entry point.
 *
 * 1. Collects every *.sql file from the migrations directory in sorted order.
 * 2. Iterates through them sequentially (order is critical for SQL migrations).
 * 3. Logs each filename, reads its content, and calls `applyMigration`.
 *
 * All errors are caught at the top level and printed with a non-zero exit code
 * so CI pipelines and process managers can detect failures reliably.
 */
async function runMigrations() {
  console.log("=== Database Migration Runner ===\n");
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  // ── 1. Discover files ──────────────────────────────────────────────────────
  let migrationFiles;
  try {
    migrationFiles = collectMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (migrationFiles.length === 0) {
    console.log("No migration files found. Nothing to apply.");
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

  // ── 2. Apply each migration in order ──────────────────────────────────────
  for (let i = 0; i < migrationFiles.length; i++) {
    const filePath = migrationFiles[i];
    const fileName = path.basename(filePath);
    const step     = `[${i + 1}/${migrationFiles.length}]`;

    console.log(`${step} Applying migration: ${fileName}`);

    let sql;
    try {
      sql = readMigrationFile(filePath);
    } catch (err) {
      console.error(`       [ERROR] Could not read file: ${filePath}`);
      console.error(`              ${err.message}`);
      process.exit(1);
    }

    try {
      await applyMigration(filePath, sql);
      console.log(`       [OK]    ${fileName}\n`);
    } catch (err) {
      console.error(`       [ERROR] Migration failed: ${fileName}`);
      console.error(`              ${err.message}`);
      process.exit(1);
    }
  }

  // ── 3. Summary ────────────────────────────────────────────────────────────
  console.log("=================================");
  console.log(`All ${migrationFiles.length} migration(s) applied successfully.`);
}

// ─── Run ──────────────────────────────────────────────────────────────────────

runMigrations().catch((err) => {
  // Safety net for any unhandled promise rejection that slips through.
  console.error("[FATAL]", err);
  process.exit(1);
});

