const MIGRATIONS_DIR = path.join(__dirname, "migrations");
const SQL_EXTENSION  = ".sql";
const ENV_FILE       = path.join(__dirname, ".env.test");

// ─── .env parser ──────────────────────────────────────────────────────────────

/**
 * Parses a .env file into a plain key/value object without any third-party
 * dependencies.  The routine intentionally handles the most common real-world
 * syntax so it stays robust in CI and local development alike.
 *
 * Rules applied line-by-line:
 *   • Leading/trailing whitespace is trimmed.
 *   • Empty lines and lines whose first non-space character is `#` are skipped.
 *   • Each line must contain `=`; the key is everything to the left of the
 *     first `=`, the raw value is everything to the right.
 *   • Both key and raw value are trimmed of surrounding whitespace.
 *   • If the value is wrapped in matching single or double quotes, those
 *     quotes are stripped, preserving interior whitespace and escape sequences
 *     exactly as written (no further processing is done inside the quotes).
 *   • Lines that produce an empty key after trimming are skipped.
 *
 * @param {string} envFilePath  Absolute path to the .env file to read.
